import{_ as s,o as e,c as n,a6 as i}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"Type System in Depth","description":"","frontmatter":{},"headers":[],"relativePath":"guide/type-system-in-depth.md","filePath":"guide/type-system-in-depth.md","lastUpdated":1781686130000}'),t={name:"guide/type-system-in-depth.md"};function p(l,a,r,o,d,c){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="type-system-in-depth" tabindex="-1">Type System in Depth <a class="header-anchor" href="#type-system-in-depth" aria-label="Permalink to “Type System in Depth”">​</a></h1><p>NG&#39;s type system combines nominal typing, structural typing, and powerful inference. This chapter explores advanced type system features.</p><h2 id="type-inference" tabindex="-1">Type Inference <a class="header-anchor" href="#type-inference" aria-label="Permalink to “Type Inference”">​</a></h2><p>NG infers types in most contexts without explicit annotations:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = 42;                 // x: i32</span></span>
<span class="line"><span>val y = 3.14;               // y: f32</span></span>
<span class="line"><span>val z = [1, 2, 3];          // z: [i32]</span></span></code></pre></div><h3 id="bidirectional-inference" tabindex="-1">Bidirectional Inference <a class="header-anchor" href="#bidirectional-inference" aria-label="Permalink to “Bidirectional Inference”">​</a></h3><p>Type information flows both from the expression to the context, and from the context to the expression:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val arr: [i32] = [];        // [] is typed as empty [i32]</span></span>
<span class="line"><span>val p: f64 = 3.14;          // 3.14 is typed as f64 (not f32)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun foo() -&gt; string {</span></span>
<span class="line"><span>    return &quot;hello&quot;;          // return type inferred from annotation</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun bar(x: i32) -&gt; i32 =&gt; x; // parameter constrained by annotation</span></span></code></pre></div><h3 id="default-numeric-types" tabindex="-1">Default Numeric Types <a class="header-anchor" href="#default-numeric-types" aria-label="Permalink to “Default Numeric Types”">​</a></h3><p>Without annotations:</p><ul><li>Integer literals default to <code>i32</code></li><li>Float literals default to <code>f32</code></li></ul><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val a = 42;                  // a: i32</span></span>
<span class="line"><span>val b = 3000000000;          // b: i32 (will wrap — use i64 or u64 explicitly)</span></span>
<span class="line"><span>val c = 42u64;               // c: u64</span></span>
<span class="line"><span>val d = 3.14;                // d: f32</span></span>
<span class="line"><span>val e = 3.14f64;             // e: f64</span></span></code></pre></div><h2 id="nominal-types" tabindex="-1">Nominal Types <a class="header-anchor" href="#nominal-types" aria-label="Permalink to “Nominal Types”">​</a></h2><p>A <strong>nominal type</strong> is a distinct type identified by its name, not its structure. NG supports two forms:</p><h3 id="newtypes" tabindex="-1">Newtypes <a class="header-anchor" href="#newtypes" aria-label="Permalink to “Newtypes”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>newtype UserId = i32;</span></span>
<span class="line"><span>newtype ProductId = i32;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val uid: UserId = UserId(1);</span></span>
<span class="line"><span>val pid: ProductId = ProductId(2);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// uid = pid;</span><span>  // TYPE ERROR: UserId != ProductId</span></span></code></pre></div><p>Newtypes are <strong>opaque</strong> — they must be explicitly wrapped and unwrapped. Use <code>as</code> to cast:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val raw: i32 = uid as i32;</span></span></code></pre></div><h3 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to “Type Aliases”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Age = i32;     // transparent: Age and i32 are the same type</span></span>
<span class="line"><span>type Point = (x: i32, y: i32);</span></span></code></pre></div><p>Type aliases are <strong>transparent</strong> — <code>Age</code> and <code>i32</code> are interchangeable in all contexts.</p><h2 id="structural-types" tabindex="-1">Structural Types <a class="header-anchor" href="#structural-types" aria-label="Permalink to “Structural Types”">​</a></h2><p>Structural types compare by their shape rather than name:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type PointA { x: i32; y: i32; }</span></span>
<span class="line"><span>type PointB { x: i32; y: i32; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// PointA and PointB are compatible because they have the same structure</span></span></code></pre></div><h2 id="union-types" tabindex="-1">Union Types <a class="header-anchor" href="#union-types" aria-label="Permalink to “Union Types”">​</a></h2><p>Union types allow a value to be one of several types:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Value = i32 | string | bool;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val v1: Value = 42;</span></span>
<span class="line"><span>val v2: Value = &quot;hello&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Runtime type check</span></span>
<span class="line"><span>const if (v1 is i32) {</span></span>
<span class="line"><span>    print(&quot;v1 is an integer&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="untagged-union-vs-tagged-union" tabindex="-1">Untagged Union vs Tagged Union <a class="header-anchor" href="#untagged-union-vs-tagged-union" aria-label="Permalink to “Untagged Union vs Tagged Union”">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Union Type (<code>A | B</code>)</th><th>Tagged Union (<code>A(x) | B(y)</code>)</th></tr></thead><tbody><tr><td>Tag</td><td>No (runtime check via <code>is</code>)</td><td>Yes (stored tag)</td></tr><tr><td>Patterns</td><td><code>is</code> operator</td><td><code>switch</code> with <code>case</code></td></tr><tr><td>Exhaustiveness</td><td>Not checked</td><td>Checked by compiler</td></tr><tr><td>Payload</td><td>The value itself</td><td>Named/numbered fields per variant</td></tr></tbody></table><h2 id="type-checking-with-is" tabindex="-1">Type Checking with <code>is</code> <a class="header-anchor" href="#type-checking-with-is" aria-label="Permalink to “Type Checking with is”">​</a></h2><p>The <code>is</code> operator checks an expression&#39;s type at runtime:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x: Value = 42;</span></span>
<span class="line"><span>val isInt = x is i32;       // true</span></span>
<span class="line"><span>val isStr = x is string;    // false</span></span></code></pre></div><p>This works with union types and tagged unions.</p><h2 id="type-queries-with-typeof" tabindex="-1">Type Queries with <code>typeof</code> <a class="header-anchor" href="#type-queries-with-typeof" aria-label="Permalink to “Type Queries with typeof”">​</a></h2><p>The <code>typeof</code> operator queries type properties at compile time:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun checkType&lt;T&gt;(value: T) {</span></span>
<span class="line"><span>    const if (is_ref&lt;T&gt;) {</span></span>
<span class="line"><span>        print(&quot;T is a reference type&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="type-casting-with-as" tabindex="-1">Type Casting with <code>as</code> <a class="header-anchor" href="#type-casting-with-as" aria-label="Permalink to “Type Casting with as”">​</a></h2><p>Use <code>as</code> to convert between related types:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x: i32 = 42;</span></span>
<span class="line"><span>val y: i64 = x as i64;        // numeric widening</span></span>
<span class="line"><span>val z = UserId(x);            // newtype wrapping</span></span>
<span class="line"><span>val raw = userId as i32;       // newtype unwrapping</span></span></code></pre></div><h2 id="literal-type-inference" tabindex="-1">Literal Type Inference <a class="header-anchor" href="#literal-type-inference" aria-label="Permalink to “Literal Type Inference”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val a = true;       // bool</span></span>
<span class="line"><span>val b = false;      // bool</span></span>
<span class="line"><span>val c = unit;       // unit</span></span>
<span class="line"><span>val d = &quot;str&quot;;      // string</span></span>
<span class="line"><span>val e = &#39;str&#39;;      // string (single quotes also OK)</span></span></code></pre></div><h2 id="exhaustiveness-checking" tabindex="-1">Exhaustiveness Checking <a class="header-anchor" href="#exhaustiveness-checking" aria-label="Permalink to “Exhaustiveness Checking”">​</a></h2><p>The type checker ensures <code>switch</code> statements cover all variants of a tagged union:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Result = Ok(i32) | Err(string);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>switch (result) {</span></span>
<span class="line"><span>    case Ok(v) { print(v); }</span></span>
<span class="line"><span>    case Err(m) { print(m); }</span></span>
<span class="line"><span>    // No &quot;otherwise&quot; needed — all variants covered</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>If you omit a variant and don&#39;t provide <code>otherwise</code>, the compiler reports an error.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Continue to <a href="./compile-time-programming">Compile-Time Programming</a> to explore NG&#39;s powerful compile-time evaluation features.</p><blockquote><p><strong>Try it:</strong> <code>example/44.type_specialization.ng</code> — Type specialization patterns <strong>Try it:</strong> <code>example/48.higher_kinded_generics.ng</code> — Higher-kinded types</p></blockquote>`,48)])])}const u=s(t,[["render",p]]);export{g as __pageData,u as default};
